css:
body{background:#fff;font-family:'Montserrat',sans-serif}
[data-bz-node="header"]{box-sizing:border-box;position:relative;background:url(/camo.jpg) center/cover;border-bottom:10px solid #8f9a96;min-height:272px;padding-bottom:0}
[data-bz-node="header"] .bz-brand{display:block}
[data-bz-node="header"] .bz-logo__img{height:170px;width:170px;border-radius:50%}
[data-bz-node="hc-addr"],[data-bz-node="hc-people"]{background:#c4a76c;padding:14px 0 0;height:107px;box-sizing:border-box;overflow:hidden}
[data-bz-node="hc-addr"]{padding-left:16px;text-align:center}
[data-bz-node="hc-addr-t"] p,[data-bz-node="hc-people-t"] p{margin:0 0 5px;line-height:25px}
[data-bz-node="hc-addr-t"] p{font:700 16px 'Playfair Display',serif;letter-spacing:.08em;text-transform:uppercase;color:#1a1a1a;text-align:center}
[data-bz-node="hc-people-t"] p{font:700 16px 'Montserrat',sans-serif;text-transform:uppercase;color:#1a1a1a}
[data-bz-node="hc-people-t"] a{color:#1a1a1a;text-decoration:underline}
[data-bz-node="main-nav"] .bz-nav{display:grid;grid-template-columns:repeat(7,1fr);gap:0;width:100%}
[data-bz-node="main-nav"] .bz-navitem{text-align:center;border-left:2px solid #b0102a;line-height:44px}
[data-bz-node="main-nav"] .bz-navitem:first-child{border-left:0}
[data-bz-node="main-nav"] .bz-navitem>a{font:800 22px 'Playfair Display',serif;color:#b0102a;text-transform:uppercase;line-height:44px}
@media (min-width:900px){
 [data-bz-node="header"]{height:272px}
 [data-bz-node="header-brand"]{position:absolute;left:22px;top:22px;width:170px}
 [data-bz-node="header-info"]{position:absolute;right:24px;top:47px;width:578px}
 [data-bz-node="header-nav-row"]{position:absolute;left:41px;right:47px;bottom:8px}
}
[data-bz-node="sell-row"],[data-bz-node="news-row"]{margin:0 42px}
[data-bz-node="sell-btn"] .bz-btn,[data-bz-node="news-h"]{display:flex;align-items:center;justify-content:center;width:100%;height:62px;background:#8b0000;border-radius:12px;color:#fff;font:800 38px 'Playfair Display',serif;letter-spacing:.06em;text-transform:uppercase;border:0;padding:0;margin:0;box-shadow:none}
[data-bz-node="sell-btn"] .bz-btn{text-decoration:none}
[data-bz-node="sell-row"]{margin-top:47px}
[data-bz-node="sell-row"] .bz-col,[data-bz-node="sell-row"] .bz-block,[data-bz-node="sell-row"] .bz-buttons{margin:0;padding:0;display:block}
[data-bz-node="info-row"]{height:264px;overflow:hidden;margin:40px 0 0;padding:0 222px}
[data-bz-node="hours-h"],[data-bz-node="contact-h"]{font:800 36px 'Playfair Display',serif;letter-spacing:.14em;text-transform:uppercase;color:#1a1a6e;margin:0 0 20px;padding-bottom:14px;border-bottom:4px solid #8b0000;margin-inline:0 38px}
[data-bz-node="contact-h"]{margin-inline:39px 0;border-bottom-color:#c0113f}
[data-bz-node="hours-t"] p,[data-bz-node="contact-t"] p{margin:0 0 44px;font:400 20px/1.15 'Montserrat',sans-serif;letter-spacing:.06em;color:#4a4a5a;text-align:center}
[data-bz-node="hours-t"] strong,[data-bz-node="contact-t"] strong{display:block;font-weight:700;color:#1a1a6e;text-transform:uppercase}
[data-bz-node="news-row"]{margin-bottom:24px;margin-top:0}
[data-bz-node="map-row"]{border-top:12px solid #8b0000;border-bottom:12px solid #8b0000}
[data-bz-node="map"]{height:176px;overflow:hidden}
[data-bz-node="main-nav"],[data-bz-node="main-nav"] .bz-menu-wrap,[data-bz-node="main-nav"] .bz-menu{width:100%;display:block}
[data-bz-node="hours-h"] *,[data-bz-node="contact-h"] *,[data-bz-node="news-h"] *{font:inherit;letter-spacing:inherit;color:inherit;margin:0}
[data-bz-node="news-h"]{letter-spacing:.06em}
[data-bz-node="map"],[data-bz-node="map"] *{border:0!important;border-radius:0!important;box-shadow:none!important}
[data-bz-node="hours-h"],[data-bz-node="contact-h"]{letter-spacing:.14em;line-height:1.2;margin-bottom:12px;word-spacing:.35em}
[data-bz-node="hours-h"] *,[data-bz-node="contact-h"] *{letter-spacing:.14em;word-spacing:.35em}
[data-bz-node="news-row"]{height:62px}
[data-bz-node="news-h"],[data-bz-node="news-h"] *{line-height:62px!important;padding:0}
[data-bz-node="sell-btn"] .bz-btn{line-height:62px}
[data-bz-node="sell-row"]{height:62px}
[data-bz-node="news-h"] *{letter-spacing:.06em;position:relative;top:3px}
